(()=>{class CartItem{constructor(data){this.pid=parseInt(data.pid);this.amount=parseInt(data.amount)||1;this.variation=data.variation}}
RockCommerceOLD.component("RcCart",{itemsLoading:!1,items:[],init(){if(RockCommerceOLD.cart)return;RockCommerceOLD.addComponent(this);RockCommerceOLD.cart=this;this.ajax=!this.$el.hasAttribute("data-noajax");this.$watch("items",this.update.bind(this));document.addEventListener("RockCommerce:ready",()=>{this.wakeup();this.update()})},addItem(data){const item=new CartItem(data);const existingItem=this.items.find((i)=>i.pid===item.pid&&i.variation===item.variation);if(existingItem){existingItem.amount+=item.amount}else{this.items.push(item)}
this.save()},get count(){let count=0;this.items.forEach((item)=>{count+=parseInt(item.amount||1)});return count},getFromLocalStorage(){return JSON.parse(localStorage.getItem("rc-cart")||"{}")},getSleepValue(){const data={_items:this.items,};return JSON.stringify(data)},reload(){this.itemsLoading=!0;RockCommerceOLD.fetch("/cart/get",{animation:this.$rcattr("rc-animation"),}).then((response)=>response.json()).then((data)=>{this.itemsLoading=!1;if(!data.id)throw new Error("No cart id");this.items=data.items}).catch(()=>{this.itemsLoading=!1;alert("Error loading cart from backend")})},save(){this.update();json=this.getSleepValue();localStorage.setItem("rc-cart",json)},update(){RockCommerceOLD.debounce("rc-cart-update",()=>{this.updateCartCount()})},updateCartCount(){let elements=document.querySelectorAll("[rc-cart-count]");elements.forEach((el)=>{el.textContent=this.count;if(this.count>0)el.removeAttribute("hidden");else el.setAttribute("hidden",!0)})},wakeup(){const data=this.getFromLocalStorage();for(const key in data){if(key==="_items"){if(this.ajax)this.reload();else this.items=data._items}}},})})()